import { join } from "../../platform/compat/path/index.js";
import { rendererLogger as logger } from "../../utils/index.js";
import { FILE_NOT_FOUND, VeryfrontError } from "../../errors/index.js";
import { withSpan } from "../../observability/tracing/otlp-setup.js";
import { getEntityBySlug, withEntityResolutionAdmission, } from "../../types/entities/getEntityInfo.js";
import { detectAppRouter, getAppRouteEntity, primeRouterDetectionCache, } from "../router-detection.js";
const PAGE_EXTENSIONS = /\.(mdx|md|tsx|jsx|ts|js)$/;
const APP_ROUTER_PAGE_PATTERN = /^page\.(mdx|md|tsx|jsx|ts|js)$/;
function isPageFile(name) {
    return PAGE_EXTENSIONS.test(name);
}
function isAppRouterPageFile(name) {
    return APP_ROUTER_PAGE_PATTERN.test(name);
}
function fileToSlug(name) {
    const slug = name.replace(PAGE_EXTENSIONS, "");
    return slug === "index" ? "/" : slug;
}
function appDirToSlug(dirPath, appDirName) {
    let relativePath = dirPath;
    if (dirPath === appDirName) {
        relativePath = "";
    }
    else if (dirPath.startsWith(`${appDirName}/`)) {
        relativePath = dirPath.slice(appDirName.length + 1);
    }
    return relativePath === "" ? "/" : `/${relativePath}`;
}
function throwIfAborted(signal) {
    if (!signal?.aborted)
        return;
    throw signal.reason ?? new DOMException("Page resolution was aborted", "AbortError");
}
export class PageResolver {
    projectDir;
    projectId;
    config;
    adapter;
    constructor(options) {
        this.projectDir = options.projectDir;
        this.projectId = options.projectId;
        this.config = options.config;
        this.adapter = options.adapter;
    }
    resolvePage(slug, options = {}) {
        const resolutionOptions = {
            ...options,
            scopeKey: options.scopeKey ?? this.projectId ?? this.projectDir,
        };
        return withSpan("routing.resolve_page", async () => {
            throwIfAborted(resolutionOptions.signal);
            const appDirName = this.config.directories?.app ?? "app";
            const pagesDirName = this.config.directories?.pages ?? "pages";
            const cacheKey = this.projectId ?? this.projectDir;
            let pageInfo;
            if (this.config.router === "app") {
                pageInfo = await getAppRouteEntity(this.projectDir, slug, this.adapter, appDirName, resolutionOptions);
                if (pageInfo) {
                    primeRouterDetectionCache(cacheKey, "app");
                }
            }
            else if (this.config.router === "pages") {
                pageInfo = await getEntityBySlug(this.projectDir, slug, this.adapter, pagesDirName, resolutionOptions);
                if (pageInfo) {
                    primeRouterDetectionCache(cacheKey, "pages");
                }
            }
            else {
                // Auto mode stays structural: detect the dominant router once, then keep
                // pages fallback available for mixed or in-transition projects.
                const useAppRouter = await withEntityResolutionAdmission(this.projectDir, this.adapter, resolutionOptions, (session) => session.awaitOperation(() => detectAppRouter(this.projectDir, this.config, this.adapter, { projectId: this.projectId })));
                if (useAppRouter) {
                    pageInfo = await getAppRouteEntity(this.projectDir, slug, this.adapter, appDirName, resolutionOptions);
                    if (!pageInfo) {
                        pageInfo = await getEntityBySlug(this.projectDir, slug, this.adapter, pagesDirName, resolutionOptions);
                    }
                }
                else {
                    pageInfo = await getEntityBySlug(this.projectDir, slug, this.adapter, pagesDirName, resolutionOptions);
                }
            }
            throwIfAborted(resolutionOptions.signal);
            if (!pageInfo) {
                throw FILE_NOT_FOUND.create({
                    detail: `Page not found: ${slug}`,
                    context: { slug, router: this.config.router ?? "auto" },
                });
            }
            return pageInfo;
        }, {
            "routing.slug": slug,
            "routing.project_dir": this.projectDir,
        });
    }
    async getAllPages() {
        const pages = new Set();
        const pagesDirName = this.config.directories?.pages ?? "pages";
        const appDirName = this.config.directories?.app ?? "app";
        const appDir = join(this.projectDir, appDirName);
        if (await this.adapter.fs.exists(appDir)) {
            await this.discoverAppRouterPages(appDir, appDirName, pages);
        }
        const pagesDir = join(this.projectDir, pagesDirName);
        if (await this.adapter.fs.exists(pagesDir)) {
            for await (const entry of this.adapter.fs.readDir(pagesDir)) {
                if (entry.isFile && isPageFile(entry.name)) {
                    pages.add(fileToSlug(entry.name));
                }
            }
        }
        for await (const entry of this.adapter.fs.readDir(this.projectDir)) {
            if (!entry.isFile || !isPageFile(entry.name) || entry.name.includes("config")) {
                continue;
            }
            pages.add(fileToSlug(entry.name));
        }
        const result = Array.from(pages);
        logger.debug("Discovered pages:", {
            count: result.length,
            pages: result,
            sources: { app: appDir, pages: pagesDir },
        });
        return result;
    }
    async discoverAppRouterPages(currentDir, appDirName, pages, relativePath = appDirName) {
        try {
            for await (const entry of this.adapter.fs.readDir(currentDir)) {
                if (entry.isFile && isAppRouterPageFile(entry.name)) {
                    pages.add(appDirToSlug(relativePath, appDirName));
                    continue;
                }
                if (!entry.isDirectory) {
                    continue;
                }
                const dirName = entry.name;
                const isRouteGroup = dirName.startsWith("(");
                const isParallelRoute = dirName.startsWith("@");
                const isPrivateFolder = dirName.startsWith("_");
                if (isParallelRoute || isPrivateFolder) {
                    continue;
                }
                if (isRouteGroup) {
                    await this.discoverAppRouterPages(join(currentDir, dirName), appDirName, pages, relativePath);
                    continue;
                }
                await this.discoverAppRouterPages(join(currentDir, dirName), appDirName, pages, `${relativePath}/${dirName}`);
            }
        }
        catch (error) {
            logger.warn("Failed to read App Router directory", {
                dir: currentDir,
                error: error instanceof Error ? error.message : String(error),
            });
        }
    }
    async pageExists(slug, options = {}) {
        try {
            await this.resolvePage(slug, options);
            return true;
        }
        catch (error) {
            if (error instanceof VeryfrontError && error.slug === "file-not-found") {
                return false;
            }
            throw error;
        }
    }
    async getRouterMode() {
        const useAppRouter = await detectAppRouter(this.projectDir, this.config, this.adapter, { projectId: this.projectId });
        return useAppRouter ? "app" : "pages";
    }
}
